1 #include <iostream>
2 #include <string>
3 using std::cin;
4 using std::cout;
5 using std::endl;
6 using std::string;
7
8 int main(void){
9
string s;
10
11
// 入力
12
cin >> s;
13
14
// 隣り合う文字を比較して判定
15
bool isgood = true;
16
if (s[0] == s[1]) isgood = false;
17
if (s[1] == s[2]) isgood = false;
18
if (s[2] == s[3]) isgood = false;
19
20
// 出力
21
if (isgood) {
22
cout << "Good" << endl;

23
} else {
24
cout << "Bad" << endl;
25
